def f(a, b):
    if a < 1:
        return 1
    return b * f(a - 2, b + 1)

def f(n):
    if n == 0:
        return 1
    if n == 1:
        return 2
    if n == 2:
        return 3
    return 2 * f(n - 1) + 3 * f(n - 3)

def f(mapp, x, y, number, dep, answer):
    if dep == 2:
        answer.add(number)
        return
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    for dx, dy in dirs:
        nx, ny = x + dx, y + dy
        if 0 <= nx < 2 and 0 <= ny < 2:
            f(mapp, nx, ny, number + mapp[nx][ny], dep + 1, answer)

